import java.io.*;

public class VariantThree {
    public static void main(String[] args) throws IOException {
        DataInputStream dis = new DataInputStream(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        long n = readLong(dis);
        long m = readLong(dis);

        if (n == 1 && m == 1) {
            pw.println(0);
        } else if (n == 1) {
            long r = m % 6;
            if (r <= 3) {
                pw.println(6 * (m / 6));
