            } else {
                pw.println(6 * (m / 6) + 4);
            }
        } else if (m == 1) {
            long r = n % 6;
            if (r <= 3) {
                pw.println(6 * (n / 6));
            } else if (r == 4) {
                pw.println(6 * (n / 6) + 2);
            } else {
                pw.println(6 * (n / 6) + 4);
            }
        } else if (n == 2 && m == 2) {
            pw.println(0);
        } else if ((n == 2 && m == 3) || (n == 3 && m == 2)) {
            pw.println(4);
        } else if ((n == 2 && m == 7) || (n == 7 && m == 2)) {
            pw.println(12);
        } else if (n % 2 == 0 || m % 2 == 0) {
            pw.println(n * m);
        } else {
            pw.println(n * m - 1);
        }
        pw.close();
    }

    static long readLong(DataInputStream dis) throws IOException {
        long res = 0;
        boolean negative = false;
        int c = dis.read();
        while (c != -1 && (c == ' ' || c == '\n' || c == '\r' || c == '\t')) {
            c = dis.read();
        }
        if (c == '-') {
            negative = true;
            c = dis.read();
        }
        while (c >= '0' && c <= '9') {
            res = res * 10 + c - '0';
            c = dis.read();
        }
        return negative ? -res : res;
    }
}
